#include <cstdint>
#include <iostream>

int main()
{
    std::int64_t kmPerSecond{ 299'792 };
    std::int64_t secondsPerDay{ 24 * 60 * 60 };

    std::int64_t days{};
    std::cin >> days;

    std::cout << "In " << days << " days light travels " << kmPerSecond * secondsPerDay * days << " km\n";
    return 0;
}
